mapper.select:
SELECT p.id, p.position_code, p.position_name, p.department_id, p.department_name,
       p.title, p.description, p.status, p.sort_order, p.create_time,
       (SELECT COUNT(*) FROM `user` u WHERE u.position_id = p.id AND u.deleted = 0) AS user_count
FROM `position` p


        AND (p.position_name LIKE CONCAT('%', #{keyword}, '%')
             OR p.position_code LIKE CONCAT('%', #{keyword}, '%'))


        AND p.department_id = #{departmentId}


        AND p.status = #{status}


ORDER BY p.sort_order, p.id
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM `position` p


        AND (p.position_name LIKE CONCAT('%', #{keyword}, '%')
             OR p.position_code LIKE CONCAT('%', #{keyword}, '%'))


        AND p.department_id = #{departmentId}


        AND p.status = #{status}
